package com.pp.shaderlod.optimization.blissspatial;
import java.util.*;import org.lwjgl.opengl.*;import net.irisshaders.iris.targets.RenderTargets;import com.pp.shaderlod.optimization.makeupao.MakeUpAoGlProof;import com.pp.shaderlod.optimization.photon.PhotonSpatialEpoch;
/** Actual adjacent producer/consumer draw proof; native implicit-LOD parity is explicit and fail-open. */
public final class BlissSpatialGl {
 public record Sample(MakeUpAoGlProof.Binding image,int compareFunction,List<Integer> swizzle){}
 public record Proof(PhotonSpatialEpoch.Output output,Map<String,Sample> inputs,boolean valid,String reason){}
 private static String refusal="none";private static void refuse(String why){if(refusal.equals("none"))refusal=why;}private static boolean rejected(String why){refuse(why);return false;}
 private BlissSpatialGl(){}
 public static int integer(int p,String name){return MakeUpAoGlProof.integer(p,name);}
 public static Sample sample(int p,String name){var b=MakeUpAoGlProof.binding(p,name);if(b==null)return null;int unit=integer(p,name),old=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{GL13.glActiveTexture(GL13.GL_TEXTURE0+unit);int s=GL11.glGetInteger(GL33.GL_SAMPLER_BINDING);int compare=s==0?GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL14.GL_TEXTURE_COMPARE_FUNC):GL33.glGetSamplerParameteri(s,GL14.GL_TEXTURE_COMPARE_FUNC);return new Sample(b,compare,List.of(GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL33.GL_TEXTURE_SWIZZLE_R),GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL33.GL_TEXTURE_SWIZZLE_G),GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL33.GL_TEXTURE_SWIZZLE_B),GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL33.GL_TEXTURE_SWIZZLE_A)));}finally{GL13.glActiveTexture(old);}}
 /** ExplicitLOD0 equals native implicit sampling only with no mip/anisotropy and identical MIN/MAG. */
 public static boolean lodParity(Sample s){return s!=null&&s.image().texture()>0&&s.image().base()==0&&s.image().width()>0&&s.image().height()>0&&s.image().aniso()==1&&s.image().min()==s.image().mag()&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(s.image().min());}
 public static boolean sameInputs(Map<String,Sample> produced,Map<String,Sample> consumer){return produced!=null&&consumer!=null&&consumer.entrySet().containsAll(produced.entrySet());}
 private static String targetStatus(RenderTargets t,int index){var x=t.get(index);return x==null?"absent":x.getMainTexture()+"/"+x.getAltTexture()+" "+x.getWidth()+"x"+x.getHeight()+" "+x.getInternalFormat();}
 private static boolean owned(RenderTargets t,int logical,int tex){var rt=t.get(logical);return rt!=null&&tex>0&&(rt.getMainTexture()==tex||rt.getAltTexture()==tex)&&rt.getWidth()==t.getCurrentWidth()&&rt.getHeight()==t.getCurrentHeight();}
 private static int output(int slot){int attachment=GL11.glGetInteger(GL20.GL_DRAW_BUFFER0+slot);if(attachment!=GL30.GL_COLOR_ATTACHMENT0+slot||GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)!=GL11.GL_TEXTURE||GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)!=0)return 0;return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);}
 private static boolean floatingWritesUnclamped(){var caps=GL.getCapabilities();if(!caps.OpenGL33)return false;int profile=GL11.glGetInteger(GL32.GL_CONTEXT_PROFILE_MASK);return (profile&GL32.GL_CONTEXT_CORE_PROFILE_BIT)!=0||GL11.glGetInteger(GL30.GL_CLAMP_FRAGMENT_COLOR)!=GL11.GL_TRUE;}
 private static boolean state(RenderTargets t,int p,boolean half,int slots){
 int[] viewport=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,viewport);int w=t.getCurrentWidth(),h=t.getCurrentHeight();
 if(!Arrays.equals(viewport,new int[]{0,0,w,half?h/2:h})||w<2||h<2||w>8192||h>8192)return rejected("viewport="+Arrays.toString(viewport)+" native="+w+"x"+h+" rate="+half);
 for(int i=0;i<slots;i++){var mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL30.glGetBooleani_v(GL11.GL_COLOR_WRITEMASK,i,mask);for(int j=0;j<4;j++)if(mask.get(j)==0)return rejected("write mask slot="+i+" component="+j);if(GL30.glIsEnabledi(GL11.GL_BLEND,i))return rejected("blend enabled slot="+i);}
 int active=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(active!=p)return rejected("current program="+active+" expected="+p);
 if(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=GL11.GL_TRUE)return rejected("program not linked="+p);
 int fbo=GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING);if(fbo<=0)return rejected("draw framebuffer="+fbo);
 int status=GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER);if(status!=GL30.GL_FRAMEBUFFER_COMPLETE)return rejected("framebuffer status="+status);
 // Observe the original six raster-state bits together so an earlier refusal cannot mask later state facts.
 var enabledStates=new ArrayList<Integer>();for(int state:new int[]{GL11.GL_CULL_FACE,GL11.GL_DEPTH_TEST,GL11.GL_STENCIL_TEST,GL11.GL_SCISSOR_TEST,GL30.GL_RASTERIZER_DISCARD,GL11.GL_COLOR_LOGIC_OP})if(GL11.glIsEnabled(state))enabledStates.add(state);
 boolean culling=enabledStates.contains(GL11.GL_CULL_FACE);int cullMode=culling?GL11.glGetInteger(GL11.GL_CULL_FACE_MODE):-1,frontFace=culling?GL11.glGetInteger(GL11.GL_FRONT_FACE):-1;
 boolean exact=BlissSpatialCull.exact();String rasterDetail=" enabledStates="+enabledStates+" cullMode="+cullMode+" frontFace="+frontFace+" exactNativeQuad="+exact;
 if(!BlissSpatialCull.allowed(culling,cullMode,frontFace,exact))return rejected("fullscreen culling refused;"+rasterDetail);
 for(int state:enabledStates)if(state!=GL11.GL_CULL_FACE)return rejected("enabled forbidden native state="+state+";"+rasterDetail);
 if(!floatingWritesUnclamped())return rejected("floating fragment writes clamped or unsupported profile");
 for(var expected:Map.of("shaderlodBridgeVersion",2,"shaderlodEnabled",1,"shaderlodOptimizationFlagsVersion",1,"shaderlodEffectsVersion",2).entrySet()){int actual=integer(p,expected.getKey());if(actual!=expected.getValue())return rejected("protocol "+expected.getKey()+"="+actual+" expected="+expected.getValue());}
 int preset=integer(p,"shaderlodPreset");if(!Set.of(0,1,2).contains(preset))return rejected("preset="+preset);return true;
 }
 private static final List<String> INPUTS=List.of("colortex0","colortex1","colortex3","colortex4","colortex6","colortex7","colortex8","colortex14","colortex15","depthtex0","depthtex1","noisetex","shadow","shadowtex0","shadowtex1","shadowcolor0");
 private static Map<String,Sample> inputs(RenderTargets t,int p){var out=new TreeMap<String,Sample>();for(String name:INPUTS){if(integer(p,name)<0)continue;var s=sample(p,name);if(!lodParity(s)){refuse("sampler "+name+" explicitLOD0 parity refused: "+s);return null;}boolean shadow=name.equals("shadow")||name.equals("shadowtex0")||name.equals("shadowtex1");if(s.image().compare()!=(shadow?GL30.GL_COMPARE_REF_TO_TEXTURE:GL11.GL_NONE)){refuse("sampler "+name+" comparison mode="+s.image().compare()+" shadow="+shadow);return null;}out.put(name,s);}
  for(String required:List.of("colortex1","colortex3","colortex7","colortex8","colortex14","colortex15","depthtex0","depthtex1"))if(!out.containsKey(required)){refuse("required active sampler absent: "+required);return null;}
  if(out.get("depthtex1").image().texture()!=t.getDepthTextureNoTranslucents().getTextureId()||out.get("depthtex0").image().texture()!=t.getDepthTexture()){refuse("native depth owners differ: depth0="+out.get("depthtex0")+" depth1="+out.get("depthtex1"));return null;}
  for(int id:new int[]{1,3,7,8,14,15})if(!owned(t,id,out.get("colortex"+id).image().texture())){refuse("native target"+id+" owner/extent differs: "+out.get("colortex"+id));return null;}
  return Map.copyOf(out);}
 private static boolean field(RenderTargets t,int index,Sample s){return s!=null&&s.image().base()==0&&s.image().compare()==GL11.GL_NONE&&s.image().format()==GL30.GL_RGBA32F&&owned(t,index,s.image().texture())&&s.swizzle().equals(List.of(GL11.GL_RED,GL11.GL_GREEN,GL11.GL_BLUE,GL11.GL_ALPHA));}
 public static Proof producer(RenderTargets t,int p,boolean half){refusal="none";int atlas=output(0);var in=inputs(t,p);var a=t.get(12);boolean valid=state(t,p,half,1)&&owned(t,12,atlas)&&a!=null&&a.getInternalFormat().name().equals("RGBA32F")&&in!=null&&in.values().stream().noneMatch(v->v.image().texture()==atlas);return new Proof(new PhotonSpatialEpoch.Output(atlas,atlas,GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),in,valid,valid?"qualified":refusal.equals("none")?"producer output="+atlas+" native12="+targetStatus(t,12)+" inputs="+(in!=null):refusal);}
 public static Proof consumer(RenderTargets t,int p){refusal="none";var atlas=sample(p,"colortex12");var in=inputs(t,p);int color=output(0);boolean valid=state(t,p,false,1)&&field(t,12,atlas)&&owned(t,3,color)&&in!=null&&color!=in.get("colortex3").image().texture()&&color!=atlas.image().texture();return new Proof(new PhotonSpatialEpoch.Output(atlas==null?0:atlas.image().texture(),atlas==null?0:atlas.image().texture(),GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),in,valid,valid?"qualified":refusal.equals("none")?"consumer output="+color+" native3="+targetStatus(t,3)+" field="+atlas+" native12="+targetStatus(t,12)+" inputs="+(in!=null):refusal);}
 public static Map<String,Integer> controls(int p){var m=new TreeMap<String,Integer>(com.pp.shaderlod.optimization.photon.PhotonSpatialGl.controls(p));
  for(String name:List.of("frameCounter","framemod8","shaderlodOptPixelScale","shaderlodBlissPixelQualificationVersion","shaderlodBlissPixelReady","shaderlodBlissPixelProfileQualified","shaderlodBlissPixelSourceQualified","shaderlodBlissPixelLayoutQualified","shaderlodBlissPixelHistoryReady","shaderlodBlissPixelNearQualified","shaderlodBlissPixelClearWeather","shaderlodBlissPixelCurrentEpoch","shaderlodBlissPixelProofEpoch","isEyeInWater","hideGUI")){int l=GL20.glGetUniformLocation(p,name);if(l>=0)m.put(name,GL20.glGetUniformi(p,l));}
  for(String name:List.of("texelSize","viewWidth","viewHeight","aspectRatio","near","far","gbufferProjection","gbufferProjectionInverse","gbufferModelView","gbufferModelViewInverse","shadowProjection","shadowModelView","shaderlodBlissPixelCurrentRain","frameTimeCounter","rainStrength","wetness","sunElevation","sunPosition")){int l=GL20.glGetUniformLocation(p,name);if(l<0)continue;int count=name.contains("Projection")||name.contains("ModelView")?16:name.equals("texelSize")?2:name.equals("sunPosition")?3:1;float[] a=new float[count];GL20.glGetUniformfv(p,l,a);for(int i=0;i<count;i++){if(!Float.isFinite(a[i]))return null;m.put(name+"["+i+"]",Float.floatToRawIntBits(a[i]));}}
  return Map.copyOf(m);
 }
 public static boolean sameControls(Map<String,Integer> produced,Map<String,Integer> consumed){return produced!=null&&consumed!=null&&consumed.entrySet().containsAll(produced.entrySet());}
 public static void upload(int p,boolean ready,int w,int h){int l=GL20.glGetUniformLocation(p,"shaderlodBlissSpatialReady");if(l>=0)GL20.glUniform1i(l,ready?1:0);l=GL20.glGetUniformLocation(p,"shaderlodBlissSpatialSize");if(l>=0)GL20.glUniform2f(l,ready?w:0,ready?h:0);}
}
